SELECT CASE WHEN duration_sec >= 398 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, event_type, SIZE(COLLECT_SET(event_type)) AS num_event_types, COUNT(*) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart_rows, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN event_type = 'page_view' THEN 1 END), 0), 2) AS duration_sec_per_page_view FROM web_events GROUP BY ROLLUP (CASE WHEN duration_sec >= 398 THEN 'PREMIUM' ELSE 'STANDARD' END, event_type) HAVING SIZE(COLLECT_SET(event_type)) >= 1
